$ctx=rxp_context($pdo);rxp_require_perm($ctx,'reports');$id=trim((string)($_GET['id']??$_POST['invoice_id']??''));
if($id===''){header('Location: invoices.php');exit;}$inv=rxp_assert_invoice($pdo,$ctx,$id);$flash='';$ft='ok';$ops=new ResellerServiceOperations($pdo,$ctx);
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 try{rxp_require_perm($ctx,'extend_user');$action=(string)($_POST['service_action']??'');$amount=(int)($_POST['amount']??0);$product=(string)($_POST['product_code']??'');$idem=(string)($_POST['idempotency_key']??'');$result=$ops->execute($inv,$action,$amount,$product,$idem);if(!empty($result['ok'])){$flash='عملیات با موفقیت انجام شد. مبلغ: '.number_format((int)$result['price']).' تومان';rxp_audit($pdo,$ctx,'service.'.$action,$id,['operation_id'=>$result['operation_id']??'','price'=>$result['price']??0]);$inv=rxp_assert_invoice($pdo,$ctx,$id);}else{$flash='عملیات ناموفق بود و در صورت کسر، مبلغ برگشت داده شد. '.$result['error'];$ft='err';}}
 catch(Throwable $e){$flash=rxp_public_exception_message($e, basename(__FILE__));$ft='err';}
}
$info=(string)($inv['user_info']??'');$decoded=json_decode($info,true);$sub='';$configs=[];if(is_array($decoded)){$sub=(string)($decoded['subscription_url']??$decoded['sub_url']??'');$configs=is_array($decoded['links']??null)?$decoded['links']:[];}elseif(preg_match('#^https?://#',$info))$sub=$info;
$renewProducts=[];if(rxp_can($ctx,'extend_user')){try{$owner=(string)($inv['refral']??'');if(!in_array($owner,$ctx['scope_ids'],true)){$owner=$ctx['id'];if(!empty($inv['bottype'])){$ob=$pdo->prepare('SELECT id_user FROM botsaz WHERE bot_token=? LIMIT 1');$ob->execute([(string)$inv['bottype']]);$candidate=(string)$ob->fetchColumn();if(in_array($candidate,$ctx['scope_ids'],true))$owner=$candidate;}}$q=$pdo->prepare('SELECT agent FROM user WHERE id=?');$q->execute([$owner]);$ag=(string)$q->fetchColumn();$q=$pdo->prepare("SELECT code_product,name_product,price_product,Volume_constraint,Service_time FROM product WHERE agent=? OR agent=? OR agent='all' ORDER BY CAST(price_product AS UNSIGNED)");$q->execute([$ag,$owner]);$renewProducts=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}}
$idem=bin2hex(random_bytes(16));
rxp_layout_start($ctx,'جزئیات سرویس','services.php');rxp_flash($flash,$ft);?>
