<div class="rxp-card"><h2>اطلاعات سرویس</h2><div class="rxp-table-wrap"><table class="rxp-table"><tr><th>مشتری</th><td><a href="users.php?id=<?=urlencode((string)$inv['id_user'])?>"><?=rxp_h($inv['id_user'])?></a></td></tr><tr><th>محصول</th><td><?=rxp_h($inv['name_product'])?></td></tr><tr><th>نام کانفیگ</th><td style="direction:ltr"><?=rxp_h($inv['username'])?></td></tr><tr><th>پنل/لوکیشن</th><td><?=rxp_h($inv['Service_location'])?></td></tr><tr><th>یادداشت</th><td><?=rxp_h($inv['note'])?></td></tr></table></div></div>
