<form method="post" class="rxp-form" onsubmit="return confirm('افزایش حجم و کسر هزینه انجام شود؟')"><input type="hidden" name="invoice_id" value="<?=rxp_h($id)?>"><input type="hidden" name="service_action" value="extra_volume"><input type="hidden" name="idempotency_key" value="<?=$idem?>"><div class="rxp-field"><label>حجم اضافه (GB)</label><input type="number" name="amount" min="1" max="10000" required></div><button class="rxp-btn">افزایش حجم</button></form>
<form method="post" class="rxp-form" onsubmit="return confirm('افزایش زمان و کسر هزینه انجام شود؟')"><input type="hidden" name="invoice_id" value="<?=rxp_h($id)?>"><input type="hidden" name="service_action" value="extra_time"><input type="hidden" name="idempotency_key" value="<?=bin2hex(random_bytes(16))?>"><div class="rxp-field"><label>زمان اضافه (روز)</label><input type="number" name="amount" min="1" max="10000" required></div><button class="rxp-btn">افزایش زمان</button></form></div>
<?php if($renewProducts):?><form method="post" class="rxp-form" style="margin-top:14px" onsubmit="return confirm('تمدید و کسر هزینه انجام شود؟')"><input type="hidden" name="invoice_id" value="<?=rxp_h($id)?>"><input type="hidden" name="service_action" value="renew"><input type="hidden" name="idempotency_key" value="<?=bin2hex(random_bytes(16))?>"><div class="rxp-field"><label>محصول تمدید</label><select name="product_code" required><?php foreach($renewProducts as $p):?><option value="<?=rxp_h($p['code_product'])?>"><?=rxp_h($p['name_product'])?> — <?=rxp_h($p['Volume_constraint'])?>GB / <?=rxp_h($p['Service_time'])?> روز — <?=rxp_money($p['price_product'])?></option><?php endforeach;?></select></div><button class="rxp-btn green">تمدید سرویس</button></form><?php endif;?><p class="rxp-muted">اگر API پنل قبل از اعمال تغییر خطا بدهد، مبلغ رزروشده خودکار برگردانده می‌شود. وضعیت‌های نامطمئن در صف «نیازمند تطبیق» قرار می‌گیرند و دوباره خودکار اجرا نمی‌شوند.</p></div><?php endif;?>
